import json
import sys

def main(config_path):
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f'config_error: {str(e)}', file=sys.stderr)
        sys.exit(2)

    tokens = config.get('tokens', [])
    jobs = config.get('jobs', [])

    with open('run.log', 'a') as log_file:
        for job in jobs:
            job_name = job.get('name')
            job_token = job.get('token')
            allowed = False
            if job_token.count('|') == 1:
                token_parts = job_token.split('|')
                if len(token_parts) == 2:
                    if token_parts[0] in tokens and token_parts[1] == 'runner':
                        allowed = True
            log_entry = json.dumps({'job': job_name, 'allowed': allowed})
            log_file.write(log_entry + '\n')

if __name__ == '__main__':
