        print('config_error: Invalid number of arguments', file=sys.stderr)
        sys.exit(2)
    main(sys.argv[1])

import json
import sys
import os

def parse_token(token):
    parts = token.split('|', 1)
    if len(parts) != 2:
        return None
    payload_str, role = parts
    try:
        payload = json.loads(payload_str)
        if payload.get('sub') is None or payload.get('role') is None:
            return None
        return payload['sub'], role
    except json.JSONDecodeError:
        return None

def process_job(job, tokens):
    token = job['token']
    sub, role = parse_token(token)
    if sub is None or role is None:
        return False
    return sub in tokens and role == 'runner'

def main():
    if len(sys.argv) != 2:
        print("config_error: Missing config path", file=sys.stderr)
        sys.exit(2)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except IOError as e:
        print(f"config_error: {e}", file=sys.stderr)
        sys.exit(2)
    except json.JSONDecodeError as e:
        print(f"config_error: Invalid JSON: {e}", file=sys.stderr)
        sys.exit(2)

    if 'tokens' not in config or 'jobs' not in config:
        print("config_error: Missing 'tokens' or 'jobs' in config", file=sys.stderr)
        sys.exit(2)

    tokens = config['tokens']
    jobs = config['jobs']

    with open('run.log', 'a') as log_file:
        for job in jobs:
            allowed = process_job(job, tokens)
            log_entry = {
                'job': job['name'],
                'allowed': str(allowed).lower()
            }
            log_file.write(json.dumps(log_entry) + '\n')

if __name__ == "__main__":
    main()

import json
import os
import sys
import logging
from pathlib import Path

logging.basicConfig(
    level=logging.INFO,
    format='%(message)s',
    handlers=[logging.StreamHandler(sys.stderr)]
)

def read_token_from_path(token_dir, token_path):
    token_file = Path(token_dir) / token_path
    if not token_file.exists():
        return None
    try:
        with open(token_file, 'r') as f:
            return f.readline().strip()
    except IOError:
        return None

def process_job(job, tokens, token_dir):
    token_value = read_token_from_path(token_dir, job['token'])
    if token_value is None:
        return False
    return token_value in tokens and job['role'] == 'runner'

def main():
    if len(sys.argv) != 2:
        logging.error("Usage: python job_runner.py <config_path>")
        sys.exit(2)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except (IOError, json.JSONDecodeError) as e:
        logging.error(f"config_error: {str(e)}")
        sys.exit(2)

    if 'tokens' not in config or 'jobs' not in config:
        logging.error("config_error: Missing required keys 'tokens' or 'jobs'")
        sys.exit(2)

    tokens = config['tokens']
    jobs = config['jobs']
    token_dir = os.getenv('TOKEN_DIR')
    if not token_dir:
        logging.error("config_error: TOKEN_DIR environment variable not set")
        sys.exit(2)

    with open('run.log', 'a') as log_file:
        for job in jobs:
            allowed = process_job(job, tokens, token_dir)
            log_entry = json.dumps({'job': job['name'], 'allowed': str(allowed)})
            log_file.write(log_entry + '\n')

if __name__ == "__main__":
    main()
